let civilTeacherCategory='全部',civilTeacherStage='全部',civilTeacherQuery='';
function civilTeachersHTML(){const list=civilTeachers.filter(t=>(civilTeacherCategory==='全部'||t.subjects.includes(civilTeacherCategory))&&(civilTeacherStage==='全部'||t.stage===civilTeacherStage)&&(t.name+t.subjects.join('')+t.focus).includes(civilTeacherQuery));return `<section class="section"><div class="page-head"><div><div class="eyebrow">按你的截图整理 · 核对于2026-10-27</div><h2>名师跟学：公开来源、方法路线与练习</h2><p>已整理 ${civilTeachers.length} 个老师／机构条目，按科目与学习阶段筛选。先选一套基础路线，再用专题练习检验；本站不做老师排名，也不保证某个分数。</p></div></div><details class="civil-boundary"><summary>资料来源等级与姓名核对说明</summary><p>机构或本人原页面、平台公开课程、学习者笔记是不同来源。公开视频不代表所有讲义可转载；本页的“配套方法／练习”为本站匹配的通用训练，不冒称老师原题。</p><p>高照是本图明确列出的姓名；李梦圆官方主讲申论、面试，常识相关的李梦娇另外列出；“超格”是机构，不是单个讲师。</p></details><div class="civil-controls"><label>科目<select id="civil-teacher-category">${['全部',...Civil.categories,'申论与面试'].map(c=>`<option ${c===civilTeacherCategory?'selected':''}>${c}</option>`).join('')}</select></label><label>学习阶段<select id="civil-teacher-stage">${['全部','基础','强化'].map(c=>`<option ${c===civilTeacherStage?'selected':''}>${c}</option>`).join('')}</select></label><label class="grow">老师或关键词<input id="civil-teacher-query" value="${esc(civilTeacherQuery)}" placeholder="例如 高照、逻辑、资料分析"></label><button class="secondary" data-teacher="search">查找</button></div><div class="concept-flow"><span><small>1 · 看基础</small>自己列式与推理</span><span><small>2 · 学方法</small>比较快解与边界</span><span><small>3 · 独立做</small>先答题再看老师讲解</span><span><small>4 · 复盘</small>记录错因与用时</span></div></section><div class="civil-teacher-grid">${list.map(t=>`<article class="section"><div class="civil-question-meta"><span class="chip">${t.stage} · ${t.subjects.join(' / ')}</span><small>来源可追溯</small></div><h2>${t.name}</h2><p><b>建议跟学：</b>${t.focus}</p><p>${t.note}</p><h3>公开资料入口</h3><div class="civil-teacher-sources">${t.links.map(l=>`<div><span class="chip">${l.kind}</span><p><a href="${l.url}" target="_blank" rel="noopener noreferrer">${l.label}</a></p><p class="small-note">${l.note}</p></div>`).join('')}</div>${t.methods.length?`<h3>本站通用方法 · 先学后练</h3><div class="filter-tabs">${t.methods.map(id=>{const m=civilMethods.find(m=>m.id===id);return `<button data-civil="method" data-id="${id}">${m.title}</button>`;}).join('')}</div><div class="hero-actions">${t.subjects.filter(c=>Civil.categories.includes(c)).map(c=>`<button class="secondary" data-civil="module" data-id="${c}">练${c}</button>`).join('')}</div>`:'<p class="small-note">申论资源供拓展阅读；当前刷题与自动判分只覆盖行测选择题。</p>'}</article>`).join('')||'<p>没有匹配条目，请换一个关键词。</p>'}</div><section class="section"><h2>哪些开源总结值得对照看？</h2><div class="civil-resource-grid"><article><h3>公考教师方法整理</h3><p>原项目把多位老师的相关方法与证据分目录管理，包含高照、龙飞、郭熙、齐麟、花生十三等。未标注独立许可，只提供原站链接；不是老师本人联合发布的课程。</p><a href="${civilTeacherSources.distill}" target="_blank" rel="noopener noreferrer">查看方法目录与来源说明</a></article><article><h3>结构化错题复盘</h3><p>郭熙相关言语复盘、判断推理与图推复盘可作为组织思路。本网站的错因、笔记与复习排程已独立实现，未安装来源仓库代码。</p><a href="${civilTeacherSources.review}" target="_blank" rel="noopener noreferrer">查看社区复盘项目</a></article></div><p class="small-note">平台搜索与页面元数据已核对，但部分B站页面限制自动访问，未逐集播放核验。若链接失效，优先从机构官网或老师已核实账号查找；不转向“全套网盘领取”搬运。</p></section>`;}
const teacherBaseShell=civilShell,teacherBaseRender=render;
civilShell=function(content){return teacherBaseShell(content).replace('<button data-civil="pane" data-id="resources"',`<button data-civil="pane" data-id="teachers" class="${civilPane==='teachers'?'active':''}" ${civilPane==='teachers'?'aria-current="page"':''}>名师跟学</button><button data-civil="pane" data-id="resources"`).replace('<h1>考公刷题</h1>',civilPane==='teachers'?'<h1>名师与方法跟学</h1>':'<h1>考公刷题</h1>');};
render=function(){if(view!=='civil'||civilPane!=='teachers')return teacherBaseRender();const s=civilSession();if(s&&!s.finished&&s.mode==='practice'&&!s.paused){Civil.recordTime(s);s.paused=true;civilPersist();}$('app').innerHTML=hubNav()+civilShell(civilTeachersHTML());const bar=document.querySelector('.subject-bar');if(bar){const wrap=document.createElement('details'),summary=document.createElement('summary');wrap.className='classroom-switcher civil-switcher';summary.textContent='考公刷题 · 切换学习领域';bar.before(wrap);wrap.append(summary,bar);}};
document.addEventListener('change',e=>{if(e.target.id==='civil-teacher-category'){civilTeacherCategory=e.target.value;render();}if(e.target.id==='civil-teacher-stage'){civilTeacherStage=e.target.value;render();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-teacher="search"]')){civilTeacherQuery=$('civil-teacher-query').value.trim();render();}});
render();
